using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DismalCycleEffect", menuName = "Data/Battle/Effects/Enemy/DismalCycle Effect")]
public class DismalCycleEffect : Effect
{
	[Header("Conjure Start of Turn")]
	[SerializeField]
	private bool conjureStartTurn;

	[SerializeField]
	[ShowIf("conjureStartTurn")]
	private ConjureAction corruptedConjureAction;

	[Header("Description")]
	[SerializeField]
	private MoveOrbsAction corruptedRevolutionAction;

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		string text = Smart.Format(base.localizationManager.GetLocalizedWheneverPlayAVirtue(), corruptedRevolutionAction.GetActionDescription(amount));
		if (conjureStartTurn)
		{
			return Smart.Format(base.localizationManager.GetLocalizedAtTheStartOfEnemiesTurn(withSpace: true), corruptedConjureAction.GetActionDescription(1)) + "\n" + text;
		}
		return text;
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(ReferenceSingleton<BattleHandler>.Instance.GetOrionAstrarium(effectOwner).MoveOrbsCoroutine(effectAmount));
		if (ReferenceSingleton<GameStateManager>.Instance.CurrentState != ReferenceSingleton<GameStateManager>.Instance.NoInteractionState)
		{
			ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		}
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		return effectAmount;
	}

	public override int OptionalActivateEffect(int effectAmount, GameObject effectOwner)
	{
		if (conjureStartTurn)
		{
			effectOwner.GetComponent<UnitEffects>().IsEffectActive(this);
			corruptedConjureAction.CastAmount(1, effectOwner);
		}
		return effectAmount;
	}
}
